printf 'variable "domain" {
  type        = string
  description = "The site domain name, for example shop.example.com."
}
' > modules/site/variables.tf

printf 'output "cert_pem" {
  description = "The site TLS certificate (PEM)."
  value       = tls_self_signed_cert.site.cert_pem
}
' > modules/site/outputs.tf

for r in tls_private_key.site tls_self_signed_cert.site local_file.nginx; do printf 'moved {
  from = %s
  to   = module.shop.%s
}

' $r $r; done > moved.tf
